import { html } from 'lit-html';
import { action } from '@storybook/addon-actions';

export default {
  title: 'Components/Form Wrapper',
  component: 'bfl-form-wrapper',
  tags: ['autodocs'],
  argTypes: {
    // No props since the bfl-form-wrapper uses slotted content and internal logic
  },
};

const Template = () => html`
  <bfl-form-wrapper>
    <!-- Child components inside the form wrapper -->
    <bfl-text-input
      name="fullName"
      label="Full Name"
      placeholder="Enter your full name"
      error-message="Full name is required"
      @inputChanged="${action('fullNameChanged')}"
    ></bfl-text-input>

    <bfl-dob-input
      name="dob"
      label="Date of Birth"
      placeholder="DD/MM/YYYY"
      error-message="Your age must be between 21 and 70 years to apply for the loan."
      @dateChanged="${action('dobChanged')}"
    ></bfl-dob-input>

    <bfl-pan-input
      name="pan"
      label="PAN Number"
      placeholder="Enter your PAN"
      error-message="Invalid PAN format"
      @inputChanged="${action('panChanged')}"
    ></bfl-pan-input>

    <bfl-checkbox-input
      name="terms"
      label="I agree to the terms and conditions"
      @checkboxChanged="${action('termsChanged')}"
    ></bfl-checkbox-input>

    <!-- External submit button -->
    <bfl-cta-button
      label="Submit"
      type="gradient"
      @buttonClick="${action('submitClicked')}"
    ></bfl-cta-button>
  </bfl-form-wrapper>
`;

